export function encodeGovernanceAction(value: GovernanceAction): xdr.ScVal {
  switch (value.type) {
    case "SetFeeBps":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("SetFeeBps"),
        nativeToScVal(asNumber(value.values[0], "GovernanceAction.SetFeeBps[0]"), { type: "u32" }),
      ]);
    case "SetStreamPolicy":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("SetStreamPolicy"),
        ((value.values[0]) == null ? xdr.ScVal.scvVoid() : addressToScVal(value.values[0])),
        encodeStreamPolicy(value.values[1]),
      ]);
    case "SetFrozen":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("SetFrozen"),
        nativeToScVal(value.values[0]),
      ]);
    case "WithdrawTreasury":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("WithdrawTreasury"),
        addressToScVal(value.values[0]),
        addressToScVal(value.values[1]),
        nativeToScVal(asBigInt(value.values[2], "GovernanceAction.WithdrawTreasury[2]"), { type: "i128" }),
      ]);
    case "NominateGovernor":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("NominateGovernor"),
        addressToScVal(value.values[0]),
      ]);
    case "ProposeUpgrade":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("ProposeUpgrade"),
        nativeToScVal(asBytes(value.values[0], "GovernanceAction.ProposeUpgrade[0]", 32), { type: "bytes" }),
        nativeToScVal(asBigInt(value.values[1], "GovernanceAction.ProposeUpgrade[1]"), { type: "u64" }),
      ]);
    case "ExecuteUpgrade":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("ExecuteUpgrade"),
      ]);
    case "MigrateStorage":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("MigrateStorage"),
        nativeToScVal(asBigInt(value.values[0], "GovernanceAction.MigrateStorage[0]"), { type: "u64" }),
        nativeToScVal(asNumber(value.values[1], "GovernanceAction.MigrateStorage[1]"), { type: "u32" }),
      ]);
    case "SetOracleConfig":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("SetOracleConfig"),
        xdr.ScVal.scvVec((value.values[0]).map((item, index) => addressToScVal(item))),
        nativeToScVal(asNumber(value.values[1], "GovernanceAction.SetOracleConfig[1]"), { type: "u32" }),
        nativeToScVal(asBigInt(value.values[2], "GovernanceAction.SetOracleConfig[2]"), { type: "u64" }),
      ]);
    case "SetSigners":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("SetSigners"),
        xdr.ScVal.scvVec((value.values[0]).map((item, index) => addressToScVal(item))),
      ]);
    case "SetVetoWindow":
      return xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("SetVetoWindow"),
        nativeToScVal(asBigInt(value.values[0], "GovernanceAction.SetVetoWindow[0]"), { type: "u64" }),
      ]);
    default:
      throw new Error(`invalid GovernanceAction type: ${String((value as { type?: unknown }).type)}`);
  }
}

export function decodeGovernanceAction(value: unknown): GovernanceAction {
  const items = asArray(value, "GovernanceAction");
  switch (asString(items[0], "GovernanceAction variant")) {
    case "SetFeeBps":
      return { type: "SetFeeBps", values: [asNumber(items[1], "GovernanceAction.SetFeeBps[0]")] };
    case "SetStreamPolicy":
      return { type: "SetStreamPolicy", values: [((items[1]) == null ? null : asString(items[1], "GovernanceAction.SetStreamPolicy[0]")), decodeStreamPolicy(items[2])] };
    case "SetFrozen":
      return { type: "SetFrozen", values: [asBool(items[1], "GovernanceAction.SetFrozen[0]")] };
    case "WithdrawTreasury":
      return { type: "WithdrawTreasury", values: [asString(items[1], "GovernanceAction.WithdrawTreasury[0]"), asString(items[2], "GovernanceAction.WithdrawTreasury[1]"), asBigInt(items[3], "GovernanceAction.WithdrawTreasury[2]")] };
    case "NominateGovernor":
      return { type: "NominateGovernor", values: [asString(items[1], "GovernanceAction.NominateGovernor[0]")] };
    case "ProposeUpgrade":
      return { type: "ProposeUpgrade", values: [asBytes(items[1], "GovernanceAction.ProposeUpgrade[0]", 32), asBigInt(items[2], "GovernanceAction.ProposeUpgrade[1]")] };
    case "ExecuteUpgrade":
      return { type: "ExecuteUpgrade", values: [] };
    case "MigrateStorage":
      return { type: "MigrateStorage", values: [asBigInt(items[1], "GovernanceAction.MigrateStorage[0]"), asNumber(items[2], "GovernanceAction.MigrateStorage[1]")] };
    case "SetOracleConfig":
      return { type: "SetOracleConfig", values: [asArray(items[1], "GovernanceAction.SetOracleConfig[0]").map((item, index) => asString(item, "GovernanceAction.SetOracleConfig[0][index]")), asNumber(items[2], "GovernanceAction.SetOracleConfig[1]"), asBigInt(items[3], "GovernanceAction.SetOracleConfig[2]")] };
    case "SetSigners":
      return { type: "SetSigners", values: [asArray(items[1], "GovernanceAction.SetSigners[0]").map((item, index) => asString(item, "GovernanceAction.SetSigners[0][index]"))] };
    case "SetVetoWindow":
      return { type: "SetVetoWindow", values: [asBigInt(items[1], "GovernanceAction.SetVetoWindow[0]")] };
    default:
      throw new Error(`unknown GovernanceAction variant: ${String(items[0])}`);
  }
}

export function encodeStreamInput(value: StreamInput): xdr.ScVal {
  return structScVal([
    ["recipient", addressToScVal(value.recipient)],
    ["token", addressToScVal(value.token)],
    ["deposit_amount", nativeToScVal(asBigInt(value.depositAmount, "StreamInput.deposit_amount"), { type: "i128" })],
    ["start_time", nativeToScVal(asBigInt(value.startTime, "StreamInput.start_time"), { type: "u64" })],
    ["end_time", nativeToScVal(asBigInt(value.endTime, "StreamInput.end_time"), { type: "u64" })],
    ["cancelable", nativeToScVal(value.cancelable)],
  ]);
}

export function decodeStreamInput(value: unknown): StreamInput {
  if (value === null || typeof value !== "object") {
    throw new Error("decodeStreamInput: expected a map");
  }
  const native = value as Record<string, unknown>;
  return {
    recipient: asString(native.recipient, "StreamInput.recipient"),
    token: asString(native.token, "StreamInput.token"),
    depositAmount: asBigInt(native.deposit_amount, "StreamInput.deposit_amount"),
    startTime: asBigInt(native.start_time, "StreamInput.start_time"),
    endTime: asBigInt(native.end_time, "StreamInput.end_time"),
    cancelable: asBool(native.cancelable, "StreamInput.cancelable"),
  };
}

